<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width,initial-scale=1">
    <title>Connect Workspace · Task Hub</title>
    <style>
        :root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#07111f;color:#e6f1ff}
        *{box-sizing:border-box}body{min-height:100vh;margin:0;display:grid;place-items:center;overflow:hidden;background:radial-gradient(circle at 50% 8%,#17304a 0,#0b1729 34%,#050b15 78%)}
        body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.35;background-image:linear-gradient(#6ee7f91a 1px,transparent 1px),linear-gradient(90deg,#6ee7f91a 1px,transparent 1px);background-size:42px 42px;mask-image:linear-gradient(to bottom,#000,transparent 70%)}
        .glow{position:fixed;width:460px;height:460px;border-radius:50%;background:#34d39918;filter:blur(70px);pointer-events:none}.card{position:relative;width:min(92vw,560px);padding:34px;border:1px solid #36516a;border-radius:28px;background:linear-gradient(145deg,#111e31f5,#081323f5);box-shadow:0 30px 90px #000b,0 0 0 1px #ffffff08 inset}.brand{display:flex;align-items:center;gap:9px;margin-bottom:28px;color:#93a9bc;font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.brand-mark{width:30px;height:30px;object-fit:contain;filter:saturate(.8)}.eyebrow{color:#67e8f9}.hero{display:flex;gap:18px;align-items:flex-start}.hero-mark{display:grid;place-items:center;flex:0 0 58px;width:58px;height:58px;border:1px solid #67e8f955;border-radius:18px;color:#67e8f9;background:#67e8f912;box-shadow:0 0 28px #67e8f91c}.hero-mark svg{width:30px;height:30px}.kicker{margin:2px 0 8px;color:#8da5ba;font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.title{margin:0;color:#f4f8ff;font-size:clamp(25px,5vw,34px);line-height:1.08;letter-spacing:-.03em}.sub{margin:12px 0 0;color:#afc1d1;font-size:14px;line-height:1.65}.workspace{display:flex;align-items:center;gap:13px;margin:28px 0 14px;padding:15px;border:1px solid #2b4660;border-radius:16px;background:#0a1728}.workspace-icon{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;color:#34d399;background:#34d39914}.workspace small{display:block;margin-bottom:4px;color:#7890a4;font-size:10px;letter-spacing:.11em;text-transform:uppercase}.workspace strong{font-size:17px;color:#f1f7ff}.status{display:flex;align-items:center;gap:8px;margin:0 0 20px;color:#a8bdd0;font-size:12px}.dot{width:7px;height:7px;border-radius:99px;background:#34d399;box-shadow:0 0 12px #34d399}.seal{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:16px 18px;margin-bottom:22px;border:1px dashed #4b6177;border-radius:16px;background:#07111e}.seal small{display:block;margin-bottom:7px;color:#7890a4;font-size:10px;letter-spacing:.12em;text-transform:uppercase}.code{font:800 24px/1 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.18em;color:#f8c96b}.seal-icon{color:#f8c96b}.actions{display:flex;gap:10px}.button{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:46px;padding:0 17px;border:1px solid transparent;border-radius:13px;font-size:13px;font-weight:800;cursor:pointer;transition:transform .15s,filter .15s}.button:hover{transform:translateY(-1px);filter:brightness(1.08)}.ok{flex:1;background:#34d399;color:#05251c;box-shadow:0 9px 25px #34d39926}.no{background:#16263a;border-color:#38516a;color:#d7e4ef}.foot{margin:20px 0 0;color:#6f879b;font-size:11px;line-height:1.5;text-align:center}svg{display:block}
        @media(max-width:520px){.card{padding:24px;border-radius:22px}.hero{gap:13px}.hero-mark{flex-basis:48px;width:48px;height:48px}.actions{flex-direction:column}.button{width:100%}.seal{align-items:flex-start;flex-direction:column;gap:12px}.code{font-size:21px}}
    </style>
</head>
<body>
    <div class="glow"></div>
    <main class="card">
        <div class="brand"><img class="brand-mark" src="/brand/macatung-mascot-icon.svg" alt=""><span class="eyebrow">Task Hub</span><span>·</span><span>Desktop Pairing</span></div>
        <section class="hero"><div class="hero-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M7 8.5h10a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2Z"/><path d="M9 5.5V3.8M15 5.5V3.8M8.5 12h.01M15.5 12h.01M9 15h6M12 8.5V6"/></svg></div><div><p class="kicker">Browser approval</p><h1 class="title">Connect Workspace</h1><p class="sub">Allow desktop companion to access all projects in the current workspace.</p></div></section>
        <div class="workspace"><div class="workspace-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="5" r="2.2"/><circle cx="5.5" cy="17" r="2.2"/><circle cx="18.5" cy="17" r="2.2"/><path d="m10.9 6.9-4.2 8.2M13.1 6.9l4.2 8.2M7.7 17h8.6"/></svg></div><div><small>Your Workspace</small><strong>{{ $session->project?->workspace?->name ?? 'Your Workspace' }}</strong></div></div>
        <p class="status"><span class="dot"></span> Scoped access · restricted to this workspace</p>
        <div class="seal"><div><small>Pairing code</small><div class="code">{{ $code }}</div></div><div class="seal-icon" aria-hidden="true"><svg viewBox="0 0 24 24" width="28" height="28" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3.3 19 6v5.2c0 4.3-2.8 7.7-7 9.5-4.2-1.8-7-5.2-7-9.5V6l7-2.7Z"/><path d="m8.8 12 2.1 2.1 4.4-4.4"/></svg></div></div>
        <div class="actions"><form method="post" action="/desktop/pairing/{{ $session->pairing_id }}/approve" style="flex:1">@csrf<input type="hidden" name="code" value="{{ $code }}"><button class="button ok" type="submit"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m5 12.5 4.2 4.2L19 7"/></svg>Authorize Connection</button></form><form method="post" action="/desktop/pairing/{{ $session->pairing_id }}/deny"><input type="hidden" name="code" value="{{ $code }}">@csrf<button class="button no" type="submit">Deny Connection</button></form></div>
        <p class="foot">Credentials are session-scoped and secrets are never exposed on screen.</p>
    </main>
</body>
</html>
